const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, VerticalAlign
} = require("docx");

// Palette
const GREEN = "2C5F5A";   // deep teal-green (vitality)
const GOLD  = "B08D57";   // warm champagne accent
const CHAR  = "2B2B2B";   // charcoal text
const SAGE  = "EAF0EE";   // soft sage fill
const CHAMP = "F6F0E6";   // champagne tint fill
const LINE  = "D8D8D8";

const CONTENT_WIDTH = 9360;

// ---------- helpers ----------
function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function h3(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_3, children: [new TextRun(text)] });
}
function body(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 120, line: 276 },
    children: [new TextRun({ text, color: CHAR, ...opts })],
  });
}
function priceLine(price, sub) {
  return new Paragraph({
    spacing: { before: 40, after: 60 },
    children: [
      new TextRun({ text: price, bold: true, color: GREEN, size: 28 }),
      ...(sub ? [new TextRun({ text: "   " + sub, color: GOLD, size: 20, italics: true })] : []),
    ],
  });
}
function bullet(text) {
  return new Paragraph({
    numbering: { reference: "dot", level: 0 },
    spacing: { after: 40, line: 264 },
    children: [new TextRun({ text, color: CHAR })],
  });
}
function rule() {
  return new Paragraph({
    spacing: { before: 120, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 1 } },
    children: [new TextRun("")],
  });
}
function spacer(after = 120) {
  return new Paragraph({ spacing: { after }, children: [new TextRun("")] });
}

// Generic table builder. cols = [{w, head}], rows = [[cell,...]]
function tbl(cols, rows, headFill = GREEN, headColor = "FFFFFF") {
  const border = { style: BorderStyle.SINGLE, size: 1, color: LINE };
  const borders = { top: border, bottom: border, left: border, right: border };
  const widths = cols.map(c => c.w);

  const headRow = new TableRow({
    tableHeader: true,
    children: cols.map((c, i) => new TableCell({
      borders, width: { size: widths[i], type: WidthType.DXA },
      shading: { fill: headFill, type: ShadingType.CLEAR },
      margins: { top: 90, bottom: 90, left: 130, right: 130 },
      verticalAlign: VerticalAlign.CENTER,
      children: [new Paragraph({
        children: [new TextRun({ text: c.head, bold: true, color: headColor, size: 21 })],
      })],
    })),
  });

  const dataRows = rows.map((r, ri) => new TableRow({
    children: r.map((cell, ci) => {
      const isObj = typeof cell === "object" && cell !== null;
      const txt = isObj ? cell.text : cell;
      const bold = isObj ? !!cell.bold : false;
      const color = isObj ? (cell.color || CHAR) : CHAR;
      const align = isObj ? cell.align : undefined;
      return new TableCell({
        borders, width: { size: widths[ci], type: WidthType.DXA },
        shading: { fill: ri % 2 === 0 ? "FFFFFF" : SAGE, type: ShadingType.CLEAR },
        margins: { top: 80, bottom: 80, left: 130, right: 130 },
        verticalAlign: VerticalAlign.CENTER,
        children: [new Paragraph({
          alignment: align,
          children: [new TextRun({ text: txt, bold, color, size: 21 })],
        })],
      });
    }),
  }));

  return new Table({
    width: { size: CONTENT_WIDTH, type: WidthType.DXA },
    columnWidths: widths,
    rows: [headRow, ...dataRows],
  });
}

// ---------- document content ----------
const children = [];

// Masthead
children.push(new Paragraph({
  spacing: { after: 40 },
  children: [new TextRun({ text: "AMARI VITALITY", bold: true, color: GREEN, size: 44 })],
}));
children.push(new Paragraph({
  spacing: { after: 40 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 4 } },
  children: [new TextRun({ text: "Memberships & Treatment Packages", color: GOLD, size: 26, italics: true })],
}));
children.push(new Paragraph({
  spacing: { before: 60, after: 240 },
  children: [new TextRun({ text: "Cookeville, Tennessee", color: CHAR, size: 20 })],
}));

children.push(body(
  "Welcome to Amari Vitality, where advanced aesthetics and whole-body wellness live under one roof. Whether you are here to refine your shape, restore your skin, or feel like yourself again from the inside out, our memberships and packages are built to make your results consistent, your visits effortless, and your investment go further. Every option below was designed to reward you for staying on your routine, because the best results come from showing up for yourself month after month."
));

children.push(spacer(80));

// ============ MEMBERSHIPS ============
children.push(h1("The Amari Vitality Membership Collection"));
children.push(body(
  "Memberships are the easiest way to look and feel your best for less. Each tier includes services every single month, member-only pricing on everything else, and perks reserved for our regulars. Choose the track that fits where you are right now. You may upgrade, pause after the initial term, or layer a wellness membership on top of an aesthetic one at any time."
));
children.push(spacer(60));

// Glow
children.push(h2("The Glow Membership"));
children.push(priceLine("$99 per month", "your easy entry into glowing skin"));
children.push(body("Each month you receive:", { bold: true }));
children.push(bullet("One B-12 Vitality injection for energy and metabolism support, a $15 value"));
children.push(bullet("10 percent off all facials, peels, and skin treatments"));
children.push(bullet("Member injectable pricing: neurotoxin at $11 per unit"));
children.push(body("Each quarter you receive:", { bold: true }));
children.push(bullet("One Express Essential Facial or Glow N' Go Peel, a $60 to $75 value"));
children.push(body("Member perks:", { bold: true }));
children.push(bullet("Birthday treatment credit and priority booking"));
children.push(rule());

// Signature
children.push(h2("The Signature Membership"));
children.push(priceLine("$199 per month", "our most popular, and our best value"));
children.push(body("Each month you receive:", { bold: true }));
children.push(bullet("One signature facial of your choice: ZO Customized Facial, Hollywood Glow Laser Facial, or Express Essential Facial"));
children.push(bullet("One B-12 Vitality injection"));
children.push(bullet("15 percent off facials, peels, skin treatments, and injectables"));
children.push(bullet("Member injectable pricing: neurotoxin at $10 per unit"));
children.push(body("Each quarter you receive:", { bold: true }));
children.push(bullet("One HydraFacial Signature, or a complimentary skin add-on of your choice (LED Light Therapy, dermaplaning, or a booster)"));
children.push(body("Member perks:", { bold: true }));
children.push(bullet("10 percent off body contouring and skin tightening"));
children.push(bullet("Birthday treatment credit and priority booking"));
children.push(rule());

// Elite
children.push(h2("The Elite Membership"));
children.push(priceLine("$349 per month", "full access for the client who wants it all"));
children.push(body("Each month you receive:", { bold: true }));
children.push(bullet("One premium facial of your choice: HydraFacial Signature, ZO Customized Facial, Hollywood Glow Laser Facial, or The Red Carpet Facial"));
children.push(bullet("One B-12 Vitality injection"));
children.push(bullet("20 percent off all services"));
children.push(bullet("Member injectable pricing: neurotoxin at $10 per unit"));
children.push(body("Each quarter you receive:", { bold: true }));
children.push(bullet("A $150 advanced treatment credit toward microneedling, peels, PRP, or laser services"));
children.push(body("Each year you receive:", { bold: true }));
children.push(bullet("One complimentary Glimpse Skin Analysis"));
children.push(bullet("15 percent off body contouring, skin tightening, and Ultherapy"));
children.push(body("Member perks:", { bold: true }));
children.push(bullet("Two guest passes per year, VIP event access, and first priority booking"));
children.push(rule());

// Vitality Wellness
children.push(h2("The Vitality Wellness Membership"));
children.push(priceLine("$129 per month", "for the client investing in how they feel"));
children.push(body("Each month you receive:", { bold: true }));
children.push(bullet("One wellness or weight management follow-up visit, a $75 value"));
children.push(bullet("One B-12 Vitality injection, a $15 value"));
children.push(bullet("Member pricing on peptide therapy and hormone optimization"));
children.push(body("Member perks:", { bold: true }));
children.push(bullet("10 percent off Men's Health and Women's Health services"));
children.push(bullet("Priority lab and appointment scheduling"));
children.push(body("Please note: when prescribed, weight management medication is billed separately at cost.", { italics: true, size: 19, color: GOLD }));
children.push(spacer(120));

// Comparison
children.push(h2("Membership at a Glance"));
children.push(tbl(
  [
    { w: 2760, head: "Membership" },
    { w: 1500, head: "Monthly" },
    { w: 5100, head: "Best For" },
  ],
  [
    [{ text: "Glow", bold: true }, "$99", "New or budget-minded clients who want a steady skin routine"],
    [{ text: "Signature", bold: true }, "$199", "The everyday client who wants a facial a month plus injectable savings"],
    [{ text: "Elite", bold: true }, "$349", "High-frequency clients who want premium services and deep discounts"],
    [{ text: "Vitality Wellness", bold: true }, "$129", "Weight management, hormone, and peptide clients"],
  ]
));
children.push(body("Memberships carry a three-month minimum commitment, then continue month to month. Unused monthly facials and injections do not roll over, which keeps your routine consistent and your results compounding.",
  { italics: true, size: 19 }));
children.push(spacer(120));

// ============ PACKAGES ============
children.push(h1("The Treatment Packages"));
children.push(body(
  "Packages bundle the treatments that work best in a series, at a meaningful saving over booking one at a time. They are the smartest way to commit to a full result rather than a single visit. Members receive their membership discount on top of package pricing where applicable."
));
children.push(spacer(60));

// Skin & Glow
children.push(h2("The Skin & Glow Collection"));
children.push(tbl(
  [
    { w: 2700, head: "Package" },
    { w: 3760, head: "What Is Included" },
    { w: 1450, head: "Value" },
    { w: 1450, head: "Investment" },
  ],
  [
    ["HydraFacial Glow Series", "Three HydraFacial Signature treatments", "$597", { text: "$499", bold: true, color: GREEN }],
    ["HydraFacial Platinum Series", "Three HydraFacial Platinum treatments", "$897", { text: "$749", bold: true, color: GREEN }],
    ["SkinPen Renewal Series", "Three SkinPen Microneedling sessions", "$1,047", { text: "$899", bold: true, color: GREEN }],
    ["Clear Skin Program", "Three Ultimate Acne Facials plus three LED Light Therapy sessions", "$840", { text: "$699", bold: true, color: GREEN }],
    ["Peel & Reveal Series", "Three ZO Stimulator Peels", "$225", { text: "$179", bold: true, color: GREEN }],
    ["The Red Carpet Trio", "Three Red Carpet Facials", "$525", { text: "$449", bold: true, color: GREEN }],
  ]
));
children.push(spacer(120));

// Injectable & Lip
children.push(h2("The Injectable & Lip Collection"));
children.push(tbl(
  [
    { w: 2700, head: "Package" },
    { w: 3760, head: "What Is Included" },
    { w: 1450, head: "Value" },
    { w: 1450, head: "Investment" },
  ],
  [
    ["The Tox Club", "Prepay for fifty units of neurotoxin and lock the member rate all year", "$600", { text: "$500", bold: true, color: GREEN }],
    ["Lip Love Bundle", "Full syringe lip filler plus a complimentary Lip Flip at your next visit", "$799", { text: "$699", bold: true, color: GREEN }],
    ["Liquid Refresh", "Cheek filler plus twenty units of neurotoxin", "$940", { text: "$799", bold: true, color: GREEN }],
  ]
));
children.push(spacer(120));

// Sculpt Collection (flagship body)
children.push(h2("The Sculpt Collection"));
children.push(body(
  "Body contouring is where Amari Vitality began, and it is still where we shine. These packages pair CoolSculpting ELITE fat reduction with PHYSIQ muscle and tone sessions and Everesse skin tightening, so you do not just lose the fat, you refine the whole shape. Flexible payment plans are available over three, six, or twelve months."
));
children.push(tbl(
  [
    { w: 2400, head: "Package" },
    { w: 4060, head: "What Is Included" },
    { w: 1450, head: "Value" },
    { w: 1450, head: "Investment" },
