children.push(tbl(
  [
    { w: 2700, head: "Package" },
    { w: 3760, head: "What Is Included" },
    { w: 1450, head: "Value" },
    { w: 1450, head: "Investment" },
  ],
  [
    ["The Ageless Lift", "Ultherapy V Lift, three RF Microneedling sessions, and one PRP Skin Rejuvenation", "$3,948", { text: "$2,999", bold: true, color: GREEN }],
    ["Collagen Restore", "Three RF Microneedling sessions with VirtueRF", "$2,550", { text: "$2,199", bold: true, color: GREEN }],
    ["Everesse Lift Duo", "Everesse Face plus Everesse Neck skin tightening", "$2,949", { text: "$2,499", bold: true, color: GREEN }],
