children.push(spacer(120));

// Laser Hair Reduction
children.push(h2("The Smooth Skin Collection"));
children.push(body(
  "All laser hair reduction is performed in a series of six for lasting results. Bundle popular areas together and save."
));
children.push(tbl(
  [
    { w: 2700, head: "Package" },
    { w: 3760, head: "What Is Included" },
    { w: 1450, head: "Value" },
    { w: 1450, head: "Investment" },
  ],
  [
    ["Smooth Skin Petite Bundle", "Upper Lip, Chin, and Underarms, six sessions each", "$1,550", { text: "$1,299", bold: true, color: GREEN }],
    ["Full Body Smooth", "Full body laser hair reduction, six sessions", "$4,999", { text: "$4,499", bold: true, color: GREEN }],
  ]
));
children.push(body("Single-area series of six are also available, from $450. Ask your provider for the full menu.",
  { italics: true, size: 19 }));
children.push(spacer(120));

// How to choose
children.push(h1("Not Sure Where to Start?"));
children.push(body("Here is the quickest way to find your fit:", { bold: true }));
children.push(bullet("If you want a facial every month and injectable savings, choose the Signature Membership."));
children.push(bullet("If you came for body and want to see a real change, start with Sculpt Transform."));
children.push(bullet("If you want to lift and firm without surgery, ask about The Ageless Lift."));
children.push(bullet("If your goal is energy, weight, or hormones, begin with the Vitality Wellness Membership or the Weight Management Jumpstart."));
children.push(spacer(60));
children.push(body(
  "Every journey at Amari Vitality begins with a consultation, where we build a plan around your goals, your timeline, and your budget. Memberships and packages may be combined, and payment plans are available on our larger packages. Pricing is current as of this menu and is subject to change."
, { size: 19, italics: true }));

// ---------- document ----------
const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: CHAR } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Arial", color: GREEN },
        paragraph: { spacing: { before: 280, after: 140 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 25, bold: true, font: "Arial", color: GREEN },
        paragraph: { spacing: { before: 160, after: 80 }, outlineLevel: 1 } },
      { id: "Heading3", name: "Heading 3", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 22, bold: true, font: "Arial", color: GOLD },
        paragraph: { spacing: { before: 100, after: 40 }, outlineLevel: 2 } },
    ],
  },
  numbering: {
    config: [
      { reference: "dot", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
        alignment: AlignmentType.LEFT, style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] },
    ],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1296, right: 1440, bottom: 1296, left: 1440 },
      },
    },
    children,
  }],
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Amari_Vitality_Memberships_and_Packages.docx", buffer);
  console.log("written");
});

