const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  HeadingLevel, BorderStyle, TabStopType
} = require("docx");

const GREEN = "2C5F5A";
const GOLD  = "B08D57";
const CHAR  = "2B2B2B";
const GRAY  = "6B6B6B";
const RIGHT_TAB = 9360;

// ---- helpers ----
function brand() {
  return new Paragraph({
    spacing: { after: 30 },
    children: [new TextRun({ text: "AMARI VITALITY", bold: true, color: GREEN, size: 40 })],
  });
}
function docTitle(text) {
  return new Paragraph({
    spacing: { after: 30 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: GOLD, space: 4 } },
    children: [new TextRun({ text, color: GOLD, italics: true, size: 26 })],
  });
}
function subTitle(text) {
  return new Paragraph({
    spacing: { before: 80, after: 220 },
    children: [new TextRun({ text, italics: true, color: GRAY, size: 21 })],
  });
}
function intro(text) {
  return new Paragraph({ spacing: { after: 200, line: 280 },
    children: [new TextRun({ text, color: CHAR, size: 22 })] });
}
function tierHead(name, price) {
  return new Paragraph({
    spacing: { before: 280, after: 30 },
    tabStops: [{ type: TabStopType.RIGHT, position: RIGHT_TAB }],
    children: [
      new TextRun({ text: name, bold: true, color: GREEN, size: 26 }),
      new TextRun({ text: "\t" + price, bold: true, color: GREEN, size: 26 }),
    ],
  });
}
function tagline(text) {
  return new Paragraph({ spacing: { after: 120 },
    children: [new TextRun({ text, italics: true, color: GOLD, size: 21 })] });
}
function label(text) {
  return new Paragraph({ spacing: { before: 100, after: 50 },
    children: [new TextRun({ text, bold: true, color: CHAR, size: 22 })] });
}
function bullet(text) {
  return new Paragraph({ numbering: { reference: "dot", level: 0 },
    spacing: { after: 40, line: 268 },
    children: [new TextRun({ text, color: CHAR, size: 22 })] });
}
function value(text) {
  return new Paragraph({ spacing: { before: 120, after: 60 },
    children: [new TextRun({ text, bold: true, color: GREEN, size: 22 })] });
}
function rule() {
  return new Paragraph({ spacing: { before: 120, after: 40 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "DADADA", space: 1 } },
    children: [new TextRun("")] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2,
    children: [new TextRun(text)] });
}
function plain(text, opts = {}) {
  return new Paragraph({ spacing: { after: 120, line: 280 },
    children: [new TextRun({ text, color: CHAR, size: 21, ...opts })] });
}
function cta(text) {
  return new Paragraph({ spacing: { before: 200 },
    children: [new TextRun({ text, bold: true, color: GREEN, size: 23 })] });
}

const baseStyles = {
  default: { document: { run: { font: "Arial", size: 22, color: CHAR } } },
  paragraphStyles: [
    { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
      run: { size: 25, bold: true, font: "Arial", color: GREEN },
      paragraph: { spacing: { before: 240, after: 100 }, outlineLevel: 1 } },
  ],
};
const baseNumbering = {
  config: [
    { reference: "dot", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
      alignment: AlignmentType.LEFT,
      style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] },
  ],
};
function sectionProps(children) {
  return {
    properties: { page: { size: { width: 12240, height: 15840 },
      margin: { top: 1296, right: 1440, bottom: 1296, left: 1440 } } },
    children,
  };
}
function makeDoc(children) {
  return new Document({ styles: baseStyles, numbering: baseNumbering, sections: [sectionProps(children)] });
}

// ============================================================
// DOC 1: MEMBERSHIP COLLECTION
// ============================================================
const m = [];
m.push(brand());
m.push(docTitle("Membership Collection"));
m.push(subTitle("Cookeville"));
m.push(intro("Every membership includes a signature treatment of your choice each month, member pricing on everything else, and a Treatment Bank so no value is ever lost."));

// Glow
m.push(tierHead("The Glow Membership", "$149 / month"));
m.push(tagline("Maintenance and radiance, your monthly reset."));
m.push(label("Choose one signature treatment each month:"));
["Signature HydraFacial",
 "ZO Customized Facial with dermaplaning",
 "Express SkinPen refresh, single area",
 "Hollywood Glow Laser Facial",
 "A B-12 and wellness boost session"].forEach(t => m.push(bullet(t)));
m.push(label("Every month you also receive:"));
["10% off all injectables, neuromodulators, and dermal fillers",
 "10% off medical grade skincare and retail",
 "10% off body contouring and all add-on treatments",
 "Treatment Bank: unused monthly value rolls over for 12 months",
 "A birthday treatment gift and one guest pass each quarter",
 "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
 "A complimentary B-12 or peptide Vitality boost added to your monthly treatment"].forEach(t => m.push(bullet(t)));
m.push(value("Estimated value: up to $230 every month, for $149."));
m.push(rule());

// Sculpt & Glow
m.push(tierHead("The Sculpt & Glow Membership", "$199 / month"));
m.push(tagline("Visible results for skin and body. Most popular."));
m.push(label("Choose one signature treatment each month:"));
["HydraFacial Platinum with a targeted booster",
 "Full SkinPen microneedling session",
 "Hollywood Glow Laser Facial with LED",
 "One PHYSIQ body contouring session",
 "A B-12 and wellness boost session"].forEach(t => m.push(bullet(t)));
m.push(label("Every month you also receive:"));
["A $25 Wellness Bank credit toward medical weight loss, peptide therapy, or injectables",
 "15% off injectables, skincare, and treatments",
 "10% off CoolSculpting, Everesse, and all body contouring",
 "Treatment Bank rollover, priority booking, and one guest pass each quarter",
 "One complimentary seasonal add-on each quarter, LED, lip, or brow",
 "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
 "A complimentary B-12 or peptide Vitality boost added to your monthly treatment"].forEach(t => m.push(bullet(t)));
m.push(value("Estimated value: $380+ every month, for $199."));
m.push(rule());

// Renewal
m.push(tierHead("The Renewal Membership", "$299 / month"));
m.push(tagline("Advanced transformation for skin and body."));
m.push(label("Choose one signature treatment each month, or bank the full value:"));
["Gold Vampire Microneedle Facial, SkinPen with PRP",
 "RF Microneedling with VirtueRF",
 "HydraFacial Platinum with all premium boosters",
 "Subnovii Plasma skin tightening, single area",
 "Bank the full monthly value toward CoolSculpting, Everesse, or CoolPeel resurfacing"].forEach(t => m.push(bullet(t)));
m.push(label("Every month you also receive:"));
["A $50 Wellness Bank credit for weight loss, peptides, injectables, or body contouring",
 "20% off injectables, skincare, and treatments",
 "15% off body contouring and device packages, with member only CoolSculpting and Everesse package pricing",
 "Treatment Bank rollover, priority booking, and two guest passes each quarter",
 "One complimentary express treatment each quarter and an annual loyalty gift",
 "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
 "A complimentary B-12 or peptide Vitality boost added to your monthly treatment"].forEach(t => m.push(bullet(t)));
m.push(value("Estimated value: $650+ every month, for $299."));
m.push(rule());

// Vitality VIP
m.push(tierHead("The Vitality VIP Membership", "$499 / month"));
m.push(tagline("Concierge access. The highest level of savings and care in the practice."));
m.push(label("Choose two signature treatments each month, or take one and bank the rest:"));
["Any two from HydraFacial Platinum, RF Microneedling, Gold Vampire Microneedle Facial, Subnovii Plasma, Ultherapy, PHYSIQ, and signature facials",
 "Take one selection and bank the remaining value toward anything you choose"].forEach(t => m.push(bullet(t)));
m.push(label("Your VIP privileges every month:"));
["A $100 Aesthetic Bank credit, the most generous offered, applied to anything: CoolSculpting, Everesse, Ultherapy, injectables, weight loss, or peptides",
 "25% off everything in the practice, including every device and big ticket procedure",
 "Member injectable pricing, the lowest per unit and per syringe rate we offer",
 "A dedicated concierge line and same week priority scheduling",
 "First access to new technology, events, and limited appointment windows",
 "One complimentary signature treatment each quarter, on top of your monthly selections",
 "An annual VIP treatment credit, for example a complimentary Everesse area or Ultherapy V Lift",
 "Complimentary numbing and aftercare, no booking fees, and four guest passes per year",
 "Invitations to private VIP events, plus premium birthday and anniversary gifts",
 "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
 "A complimentary B-12 or peptide Vitality boost added to your monthly treatment"].forEach(t => m.push(bullet(t)));
m.push(value("Estimated value: $1,300+ every month, for $499."));

m.push(h2("How Your Membership Works"));
m.push(plain("Your monthly fee secures your signature treatment and unlocks member pricing across the entire practice. Any treatment value you do not use banks automatically and stays available for 12 months, so your investment is never lost. Wellness Bank and Aesthetic Bank credits stack and roll over with it."));
m.push(plain("Memberships begin with a three month commitment, then continue month to month. Upgrade, downgrade, or pause anytime after the first three months. Member pricing reflects the practice's standard rates and cannot be combined with other promotions. Treatment selections and values are illustrative and confirmed at booking."));
m.push(cta("Ready to join? Speak with your provider or our front desk today."));

Packer.toBuffer(makeDoc(m)).then(b =>
  fs.writeFileSync("/home/claude/Amari_Vitality_Membership_Collection.docx", b).valueOf ? null : null
).then(() => console.log("doc1 done"));

// ============================================================
// DOC 2: THE SIGNATURE YEAR
// ============================================================
const y = [];
y.push(brand());
y.push(docTitle("The Signature Year"));
