      ...(trailing ? [new TextRun({ text: "     " + trailing, color: CHAR, size: 21 })] : []),
    ] });
}

// tier selection table
function selectionTable() {
  const border = { style: BorderStyle.SINGLE, size: 1, color: LINE };
  const borders = { top: border, bottom: border, left: border, right: border };
  const cols = [
    { w: 1100, h: "Select" },
    { w: 3600, h: "Membership" },
    { w: 2260, h: "Monthly Fee" },
    { w: 2400, h: "Signature Treatments" },
  ];
  const head = new TableRow({ tableHeader: true, children: cols.map(c => new TableCell({
    borders, width: { size: c.w, type: WidthType.DXA },
    shading: { fill: GREEN, type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text: c.h, bold: true, color: "FFFFFF", size: 20 })] })],
  })) });
  const data = [
    ["\u2610", "Amari Signature", "$99 / month", "One per month"],
    ["\u2610", "Amari Elite", "$179 / month", "One per month"],
    ["\u2610", "Amari Prestige", "$249 / month", "One per month"],
    ["\u2610", "Amari VIP", "$459 / month", "Two per month"],
  ];
  const rows = data.map((r, ri) => new TableRow({ children: r.map((cell, ci) => new TableCell({
    borders, width: { size: cols[ci].w, type: WidthType.DXA },
    shading: { fill: ri % 2 === 0 ? "FFFFFF" : "F3F6F5", type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({
      alignment: ci === 0 ? AlignmentType.CENTER : AlignmentType.LEFT,
      children: [new TextRun({ text: cell, bold: ci === 1, color: CHAR, size: ci === 0 ? 26 : 21 })] })],
  })) }));
  return new Table({ width: { size: CONTENT_WIDTH, type: WidthType.DXA },
    columnWidths: cols.map(c => c.w), rows: [head, ...rows] });
}

function sigLineLabel(text) {
  return new Paragraph({ spacing: { before: 260, after: 0 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: CHAR, space: 2 } },
    children: [new TextRun("")] });
}
function sigCaption(text) {
  return new Paragraph({ spacing: { after: 40 },
    children: [new TextRun({ text, color: GRAY, size: 18 })] });
}

const c = [];

// Header
c.push(subtitle("Amari Vitality"));
c.push(title("Membership Agreement"));
c.push(rule());

c.push(body("This Membership Agreement (the \u201cAgreement\u201d) is entered into by and between Amari Vitality (the \u201cPractice,\u201d \u201cwe,\u201d or \u201cus\u201d), located in Cookeville, Tennessee, and the individual identified in the signature section below (the \u201cMember,\u201d \u201cyou\u201d). This Agreement becomes effective on the date the Member signs below (the \u201cEffective Date\u201d)."));

c.push(section("1", "Membership Selection"));
c.push(body("The Member selects the following membership tier. Monthly fees are stated in United States dollars and are billed each month as described in Section 4."));
c.push(selectionTable());
c.push(new Paragraph({ spacing: { after: 120 }, children: [new TextRun("")] }));
c.push(body("The specific treatments, discounts, and benefits associated with each tier are described in the Amari Vitality Membership Collection in effect on the Effective Date (the \u201cMembership Collection\u201d), which is incorporated into this Agreement by reference. If a conflict exists between the Membership Collection and this Agreement, this Agreement controls."));

c.push(section("2", "Core Membership Benefits"));
c.push(body("Each membership includes, at a minimum: (a) one signature treatment each month selected from the options listed for the Member\u2019s tier, or two signature treatments each month for the Amari VIP tier; (b) a member discount on other services, products, and treatments as stated for the Member\u2019s tier; and (c) participation in the Treatment Bank described in Section 6. Additional perks vary by tier and are described in the Membership Collection."));

c.push(section("3", "Term and Initial Commitment"));
c.push(body("This Agreement begins on the Effective Date and continues for an initial term of three (3) consecutive months (the \u201cInitial Term\u201d). The Member agrees to pay the monthly fee for each month of the Initial Term. After the Initial Term, the membership continues on a month-to-month basis until cancelled in accordance with Section 10."));

c.push(section("4", "Monthly Fees and Recurring Payment Authorization"));
c.push(body("The Member authorizes the Practice to charge the monthly membership fee to the payment method the Member places on file, automatically and on a recurring basis, on the same day each month (the \u201cBilling Date\u201d), beginning on the Effective Date. This authorization remains in effect until the membership is cancelled under Section 10 and all amounts owed are paid. The Member is responsible for keeping a valid payment method on file."));
c.push(initialLine());

c.push(section("5", "Declined or Late Payments"));
c.push(body("If a scheduled payment is declined, the Practice may attempt to charge the payment method again and may suspend membership benefits, including signature treatments and member pricing, until the balance is paid. Banked value does not accrue during any period of suspension. If payment remains unpaid for thirty (30) days, the Practice may terminate the membership, and any unused banked value may be forfeited as described in Section 6."));

c.push(section("6", "Treatment Bank (Banked Value)"));
c.push(body("If the Member does not use the monthly signature treatment in the month it is provided, the value of that treatment is credited to the Member\u2019s Treatment Bank. Banked value: (a) is stated as a service credit and has no cash value; (b) remains available for twelve (12) months from the month in which it was earned, and expires after that period; (c) may be applied toward services offered by the Practice, subject to medical eligibility and scheduling; (d) is personal to the Member and may not be transferred, sold, or redeemed for cash; and (e) upon cancellation or termination of the membership, remains redeemable for thirty (30) days after the effective date of cancellation, after which any remaining banked value expires."));
c.push(initialLine());

c.push(section("7", "Signature Treatments and Substitutions"));
c.push(body("Signature treatments are subject to provider availability, medical eligibility, and the clinical judgment of the Practice. The Practice may substitute a treatment of comparable value where appropriate. A signature treatment not used in a given month converts to banked value under Section 6 and does not entitle the Member to a refund."));

c.push(section("8", "Member Discounts"));
c.push(body("Member discounts apply to the Practice\u2019s standard rates for the items described in the Member\u2019s tier. Member discounts cannot be combined with other discounts, promotions, packages, or special offers unless the Practice states otherwise in writing."));

c.push(section("9", "Medical Services, Candidacy, and Consent"));
c.push(body("The membership is not medical insurance and is not a substitute for medical care. Enrollment does not guarantee that the Member is a candidate for any particular treatment. All treatments require a separate medical evaluation, a determination of candidacy, and the Member\u2019s signed informed consent before they are performed. The Practice retains sole clinical discretion to decline, modify, or discontinue any treatment. Results vary from person to person and are not guaranteed."));
c.push(initialLine());

c.push(section("10", "Cancellation"));
c.push(body("After the Initial Term, either party may cancel this Agreement by providing at least thirty (30) days written notice. The membership and its benefits continue through the end of the billing month in which the notice period ends. Monthly fees already charged are non-refundable. Banked value is handled as described in Section 6."));

c.push(section("11", "Pause and Freeze"));
c.push(body("After the Initial Term, the Member may request to pause the membership for a period of one (1) to three (3) months. During a pause, monthly fees are not charged, membership benefits are suspended, and new banked value does not accrue. Previously banked value remains subject to its original twelve (12) month expiration."));

c.push(section("12", "Upgrade and Downgrade"));
c.push(body("After the Initial Term, the Member may request to change tiers. Approved changes take effect on the next Billing Date. A downgrade does not entitle the Member to a refund of any difference in fees already paid."));

c.push(section("13", "Refunds"));
c.push(body("Except where required by applicable law, monthly membership fees are non-refundable, including fees paid for months in which the Member does not use any benefit. Banked value and unused benefits have no cash value and are not refundable."));
c.push(initialLine());

c.push(section("14", "Changes to Pricing, Benefits, and Treatment Menu"));
c.push(body("The Practice may change membership pricing, benefits, discounts, and the available treatment menu. The Practice will provide at least thirty (30) days notice of any increase to the Member\u2019s monthly fee. The Member\u2019s continued membership after the effective date of a change constitutes acceptance of that change. A Member who does not accept a fee increase may cancel under Section 10."));

c.push(section("15", "Guest Passes"));
c.push(body("Guest passes, where included, are subject to scheduling, medical eligibility, and the guest\u2019s signed consent. Guest passes have no cash value and may not be sold."));

c.push(section("16", "Non-Transferability"));
c.push(body("The membership and its benefits are personal to the Member and may not be assigned, sold, shared, or transferred, except for guest passes as expressly provided."));

c.push(section("17", "Appointments, Late Cancellation, and No-Show Policy"));
c.push(body("Treatments and signature treatments require a scheduled appointment. The Member agrees to the Practice\u2019s late cancellation and no-show policy in effect at the time, which may include a fee. A signature treatment missed due to a late cancellation or no-show converts to banked value under Section 6 and is not otherwise credited."));

c.push(section("18", "Communications"));
c.push(body("The Member consents to receive communications from the Practice regarding billing, appointments, and the membership by phone, text message, and email at the contact information provided. The Member may opt out of promotional messages at any time."));

c.push(section("19", "Assumption of Risk and Limitation of Liability"));
c.push(body("The clinical risks of each treatment are described in the separate informed consent the Member signs for that treatment, and that consent governs those risks. To the fullest extent permitted by law, the Practice is not liable for indirect, incidental, or consequential damages arising from the membership itself. Nothing in this Agreement limits any liability that cannot be limited under applicable law."));

c.push(section("20", "Governing Law and Venue"));
c.push(body("This Agreement is governed by the laws of the State of Tennessee. Any dispute arising from this Agreement will be resolved in the state or federal courts located in Putnam County, Tennessee."));

c.push(section("21", "Entire Agreement, Severability, and Waiver"));
c.push(body("This Agreement, together with the Membership Collection and any treatment consents, is the entire agreement between the parties regarding the membership and supersedes any prior understanding. If any provision is found unenforceable, the remaining provisions remain in effect. The failure of the Practice to enforce any provision is not a waiver of that provision."));

c.push(section("22", "Acknowledgment"));
c.push(body("By signing below, the Member acknowledges that the Member has read and understood this Agreement, including the recurring monthly billing in Section 4, the non-refundable nature of fees in Section 13, the expiration of banked value in Section 6, and the clinical discretion described in Section 9."));

// Signature section
c.push(new Paragraph({ spacing: { before: 240, after: 100 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD, space: 2 } },
  children: [new TextRun({ text: "Member Enrollment and Signature", bold: true, color: GREEN, size: 24 })] }));

c.push(fieldLine("Member name (printed):"));
c.push(fieldLine("Date of birth:", "________________", "Email: ______________________________"));
