c.push(sigLineLabel());
c.push(sigCaption("Member signature                                                                                          Date"));

c.push(new Paragraph({ spacing: { before: 200, after: 100 },
  children: [new TextRun({ text: "Payment Authorization", bold: true, color: GREEN, size: 22 })] }));
c.push(body("I authorize Amari Vitality to charge my payment method on file for the monthly membership fee on a recurring basis as described in Section 4, until I cancel in accordance with Section 10."));
c.push(fieldLine("Payment method on file (last four digits):", "____  ____  ____  ____"));

c.push(sigLineLabel());
c.push(sigCaption("Member signature                                                                                          Date"));

c.push(new Paragraph({ spacing: { before: 220, after: 100 },
  children: [new TextRun({ text: "Practice Representative", bold: true, color: GREEN, size: 22 })] }));
c.push(fieldLine("Name:", "________________________________", "Title: ________________________"));

c.push(sigLineLabel());
c.push(sigCaption("Authorized signature                                                                                     Date"));

const doc = new Document({
  styles: { default: { document: { run: { font: "Arial", size: 21, color: CHAR } } } },
