const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  HeadingLevel, BorderStyle, TabStopType
} = require("docx");

const GREEN = "2C5F5A";
const GOLD  = "B08D57";
const CHAR  = "2B2B2B";
const GRAY  = "6B6B6B";
const RIGHT_TAB = 9360;

function brand() {
  return new Paragraph({ spacing: { after: 30 },
    children: [new TextRun({ text: "AMARI VITALITY", bold: true, color: GREEN, size: 40 })] });
}
function docTitle(text) {
  return new Paragraph({ spacing: { after: 30 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: GOLD, space: 4 } },
    children: [new TextRun({ text, color: GOLD, italics: true, size: 26 })] });
}
function subTitle(text) {
  return new Paragraph({ spacing: { before: 80, after: 220 },
    children: [new TextRun({ text, italics: true, color: GRAY, size: 21 })] });
}
function intro(text) {
  return new Paragraph({ spacing: { after: 200, line: 280 },
    children: [new TextRun({ text, color: CHAR, size: 22 })] });
}
function tierHead(name, price) {
  return new Paragraph({ spacing: { before: 300, after: 30 },
    tabStops: [{ type: TabStopType.RIGHT, position: RIGHT_TAB }],
    children: [
      new TextRun({ text: name, bold: true, color: GREEN, size: 27 }),
      new TextRun({ text: "\t" + price, bold: true, color: GREEN, size: 27 }),
    ] });
}
function tagline(text) {
  return new Paragraph({ spacing: { after: 120 },
    children: [new TextRun({ text, italics: true, color: GOLD, size: 21 })] });
}
function label(text) {
  return new Paragraph({ spacing: { before: 100, after: 50 },
    children: [new TextRun({ text, bold: true, color: CHAR, size: 22 })] });
}
function bullet(text) {
  return new Paragraph({ numbering: { reference: "dot", level: 0 },
    spacing: { after: 40, line: 268 },
    children: [new TextRun({ text, color: CHAR, size: 22 })] });
}
function value(text) {
  return new Paragraph({ spacing: { before: 120, after: 60 },
    children: [new TextRun({ text, bold: true, color: GREEN, size: 22 })] });
}
function rule() {
  return new Paragraph({ spacing: { before: 140, after: 40 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "DADADA", space: 1 } },
    children: [new TextRun("")] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function plain(text) {
  return new Paragraph({ spacing: { after: 120, line: 280 },
    children: [new TextRun({ text, color: CHAR, size: 21 })] });
}
function cta(text) {
  return new Paragraph({ spacing: { before: 200 },
    children: [new TextRun({ text, bold: true, color: GREEN, size: 23 })] });
}
function tier(name, price, tag, chooseLabel, treatments, perks, valLine) {
  const arr = [tierHead(name, price), tagline(tag), label(chooseLabel)];
  treatments.forEach(t => arr.push(bullet(t)));
  arr.push(label("Membership perks:"));
  perks.forEach(t => arr.push(bullet(t)));
  arr.push(value(valLine));
  return arr;
}

const m = [];
m.push(brand());
m.push(docTitle("Membership Collection"));
m.push(subTitle("Cookeville"));
m.push(intro("Every membership includes a signature treatment of your choice each month, a member discount on everything else, and a Treatment Bank so no value is ever lost."));

tier("Amari Signature", "$99 / month",
  "Your monthly glow, beautifully maintained.",
  "Choose one signature treatment each month:",
  ["ZO Customized Facial with dermaplaning",
   "Hollywood Glow Laser Facial",
   "Extra Small Laser Hair area",
   "IV Therapy"],
  ["10% off medical grade skincare and retail",
   "10% off body contouring and all add-on treatments",
   "Treatment Bank: unused monthly value rolls over for 12 months",
   "A mini birthday treatment gift and one guest pass each quarter",
   "No injection fee for fillers or tox"],
  "Estimated value: up to $230 every month, for $99.").forEach(p => m.push(p));
m.push(rule());

tier("Amari Elite", "$179 / month",
  "Visible results for skin and body. Most popular.",
  "Choose one signature treatment each month:",
  ["HydraFacial Signature with dermaplane and LED",
   "One PHYSIQ or Cooltone body contouring session",
   "Small Laser Hair area"],
  ["10% off all injectables, neuromodulators, and dermal fillers",
   "10% off medical grade skincare and retail",
   "10% off body contouring and all add-on treatments",
   "Treatment Bank: unused monthly value rolls over for 12 months",
   "A birthday treatment gift and one guest pass each quarter",
   "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
   "A complimentary B-12 or peptide Vitality boost added to your monthly treatment"],
  "Estimated value: $380+ every month, for $199.").forEach(p => m.push(p));
m.push(rule());

tier("Amari Prestige", "$249 / month",
  "Advanced transformation, skin and body.",
  "Choose one signature treatment each month, or bank the full value:",
  ["Skinpen Microneedling",
   "HydraFacial Platinum",
   "Everesse Undereye or Browlift",
   "Medium Laser Hair area",
   "Bank the full value toward CoolSculpting or Everesse"],
  ["15% off all injectables, neuromodulators, and dermal fillers",
   "15% off medical grade skincare and retail",
   "15% off body contouring and all add-on treatments",
   "Treatment Bank: unused monthly value rolls over for 12 months",
   "A birthday treatment gift and one guest pass each quarter",
   "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
   "A complimentary B-12 or peptide Vitality boost added to your monthly treatment"],
  "Estimated value: $650+ every month, for $299.").forEach(p => m.push(p));
m.push(rule());

tier("Amari VIP", "$459 / month",
  "Concierge access, at the best rates we offer.",
  "Choose two signature treatments each month, or take one and bank the rest:",
  ["Any two of these treatments: HydraFacial Platinum, Skinpen Microneedle Facial, Chemical Peel, Cooltone or PHYSIQ",
   "Coolpeel or Light CO2 treatment on the hands",
   "Large Laser hair area"],
  ["20% off everything",
   "A dedicated concierge line and same week booking",
   "Treatment Bank: unused monthly value rolls over for 12 months",
   "A birthday treatment gift and one guest pass each quarter",
   "Member pricing on peptide therapy and longevity programs, plus a complimentary longevity and wellness consultation",
   "A complimentary B-12 or peptide Vitality boost added to your monthly treatment",
   "VIP access to all new treatments, events and membership perks"],
  "Estimated value: $1,300+ every month, for $499.").forEach(p => m.push(p));

m.push(h2("How Your Membership Works"));
m.push(plain("Your monthly fee covers your signature treatment and unlocks your member discount on everything else. Any value you do not use each month banks automatically and stays available for 12 months, so nothing is ever lost."));
m.push(plain("Memberships begin with a three month commitment, then continue month to month. Cancel, upgrade, or pause anytime after that. Selections and values are confirmed at booking."));
m.push(cta("Ready to join? Speak with your provider or our front desk today."));

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: CHAR } } },
    paragraphStyles: [
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 25, bold: true, font: "Arial", color: GREEN },
        paragraph: { spacing: { before: 240, after: 100 }, outlineLevel: 1 } },
    ],
  },
  numbering: { config: [
    { reference: "dot", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
      alignment: AlignmentType.LEFT,
      style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] },
  ] },
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 },
      margin: { top: 1296, right: 1440, bottom: 1296, left: 1440 } } },
    children: m,
  }],
});

Packer.toBuffer(doc).then(b => {
  fs.writeFileSync("/mnt/user-data/outputs/Amari_Vitality_Membership_Collection.docx", b);
  console.log("done");
});

