const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, AlignmentType, LevelFormat,
  HeadingLevel, BorderStyle, WidthType, ShadingType, VerticalAlign,
  Table, TableRow, TableCell
} = require("docx");

const GREEN = "2C5F5A";
const GOLD  = "B08D57";
const CHAR  = "2B2B2B";
const GRAY  = "6B6B6B";
const LINE  = "D8D8D8";
const CONTENT_WIDTH = 9360;

function brand() {
  return new Paragraph({ spacing: { after: 30 },
    children: [new TextRun({ text: "AMARI VITALITY", bold: true, color: GREEN, size: 40 })] });
}
function docTitle(text) {
  return new Paragraph({ spacing: { after: 30 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 10, color: GOLD, space: 4 } },
    children: [new TextRun({ text, color: GOLD, italics: true, size: 26 })] });
}
function subTitle(text) {
  return new Paragraph({ spacing: { before: 80, after: 200 },
    children: [new TextRun({ text, italics: true, color: GRAY, size: 21 })] });
}
function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function group(text) {
  return new Paragraph({ spacing: { before: 160, after: 40 },
    children: [new TextRun({ text, bold: true, color: GREEN, size: 23 })] });
}
function moment(text) {
  return new Paragraph({ spacing: { before: 90, after: 30 },
    children: [new TextRun({ text, bold: true, color: CHAR, size: 21 })] });
}
function say(text) {
  return new Paragraph({ spacing: { after: 110, line: 276 }, indent: { left: 300 },
    border: { left: { style: BorderStyle.SINGLE, size: 18, color: GOLD, space: 14 } },
    children: [new TextRun({ text: "\u201c" + text + "\u201d", italics: true, color: CHAR, size: 22 })] });
}
function body(text, opts = {}) {
  return new Paragraph({ spacing: { after: 120, line: 280 },
    children: [new TextRun({ text, color: CHAR, size: 22, ...opts })] });
}
function bullet(text) {
  return new Paragraph({ numbering: { reference: "dot", level: 0 },
    spacing: { after: 50, line: 268 },
    children: [new TextRun({ text, color: CHAR, size: 22 })] });
}
function bulletBold(lead, rest) {
  return new Paragraph({ numbering: { reference: "dot", level: 0 },
    spacing: { after: 50, line: 268 },
    children: [new TextRun({ text: lead, bold: true, color: CHAR, size: 22 }),
               new TextRun({ text: rest, color: CHAR, size: 22 })] });
}
function rule() {
  return new Paragraph({ spacing: { before: 140, after: 40 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: "DADADA", space: 1 } },
    children: [new TextRun("")] });
}

function triggerTable() {
  const border = { style: BorderStyle.SINGLE, size: 1, color: LINE };
  const borders = { top: border, bottom: border, left: border, right: border };
  const cols = [{ w: 3760, h: "When the client says" }, { w: 1900, h: "Move them to" }, { w: 3700, h: "Why it wins" }];
  const head = new TableRow({ tableHeader: true, children: cols.map(c => new TableCell({
    borders, width: { size: c.w, type: WidthType.DXA },
    shading: { fill: GREEN, type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text: c.h, bold: true, color: "FFFFFF", size: 20 })] })],
  })) });
  const data = [
    ["\u201cI want to tone up or lose a little\u201d", "Elite or Prestige", "PHYSIQ or Cooltone every month, or bank toward CoolSculpting"],
    ["\u201cI get tox or filler pretty often\u201d", "Elite and up", "Injectable discounts, and Signature already waives the injection fee"],
    ["\u201cI want firmer, younger skin\u201d", "Prestige", "SkinPen, HydraFacial Platinum, and Everesse each month"],
    ["\u201cI want to save toward CoolSculpting\u201d", "Prestige", "Bank the full monthly value straight toward the device"],
    ["\u201cI want a little of everything\u201d", "VIP", "Two signature treatments a month and 20% off everything"],
    ["\u201cI want my hands or big laser areas\u201d", "VIP", "CoolPeel on the hands and large laser areas are included"],
    ["\u201cI am in every month buying extras\u201d", "One tier up", "The add-ons already cost more than the upgrade does"],
  ];
  const rows = data.map((r, ri) => new TableRow({ children: r.map((cell, ci) => new TableCell({
    borders, width: { size: cols[ci].w, type: WidthType.DXA },
    shading: { fill: ri % 2 === 0 ? "FFFFFF" : "F3F6F5", type: ShadingType.CLEAR },
    margins: { top: 70, bottom: 70, left: 120, right: 120 }, verticalAlign: VerticalAlign.CENTER,
    children: [new Paragraph({ children: [new TextRun({ text: cell, bold: ci === 1, color: CHAR, size: 20 })] })],
  })) }));
  return new Table({ width: { size: CONTENT_WIDTH, type: WidthType.DXA }, columnWidths: cols.map(c => c.w), rows: [head, ...rows] });
}

const c = [];
c.push(brand());
c.push(docTitle("In-Treatment Upsell and Tier Upgrade Script"));
c.push(subTitle("For providers and front desk. Internal use."));

// Ground rules
c.push(h1("The Amari Way to Offer"));
c.push(body("Every offer starts with what the client already told you she wants. We are not selling from a menu, we are giving her the fastest path to the result she came in for. Follow five rules and it never feels like a pitch:"));
[["Lead with her goal. ", "Repeat back what she said she wants, then connect the add-on or tier to it."],
 ["One thing at a time. ", "Make a single clear recommendation, not a list. A list feels like a sale, one idea feels like advice."],
 ["Offer in the room, close at checkout. ", "Plant the add-on while she is in the chair, confirm the plan and the membership at the desk."],
 ["Assume yes, stay warm. ", "Ask \u201cwant me to add that today?\u201d as if it is the natural next step, because it is."],
 ["Let the math close it. ", "When the total of what she wants is more than the next tier, show her that number and let it decide."]].forEach(x => c.push(bulletBold(x[0], x[1])));

// PART 1
c.push(h1("Part 1. Add-Ons to Offer During Each Treatment"));
c.push(body("Offer the add-on at the moment it makes sense, usually while the treatment is already working. Here is what pairs naturally with each service, and how to ask.", { italics: true, color: GRAY, size: 21 }));

c.push(group("During any facial (ZO Customized, HydraFacial, Hollywood Glow)"));
c.push(moment("LED Light Therapy, offered once the skin is cleansed:"));
c.push(say("Your skin is already responding beautifully. I would love to finish with ten minutes of LED, it calms redness and boosts collagen while you just relax. Want me to include it today?"));
c.push(moment("Hydro jelly mask or a booster, offered near the end:"));
c.push(say("Since we are already here, a hydro jelly mask would lock all this hydration in and you will walk out glowing. It is a small add-on, want me to add it?"));
c.push(moment("Perk eye or lip, offered as a finishing touch:"));
c.push(say("Want me to brighten up your under-eye area while we are at it? It is quick, and it makes such a difference in photos."));

c.push(group("During injectables (tox and filler)"));
c.push(body("Remember Signature members pay no injection fee, so add-ons here feel effortless.", { italics: true, color: GRAY, size: 21 }));
c.push(moment("B-12 boost, offered while she is settled in:"));
c.push(say("While you are here, a lot of clients add a quick B-12 for energy, it is a two-second shot. Want me to add one today?"));
c.push(moment("Lip flip, offered alongside tox:"));
c.push(say("If we add just a few units to your lip, we can give you that soft flip that makes your lipstick sit perfectly. Want me to include it?"));
c.push(moment("A second area, offered while she is already numb:"));
c.push(say("You mentioned your cheeks earlier. We could do a touch there today while you are already numb, or plan it for next visit. What feels right?"));

c.push(group("During body contouring (CoolSculpting, PHYSIQ, Cooltone, Everesse)"));
c.push(moment("PHYSIQ or Cooltone to tone, offered with CoolSculpting:"));
c.push(say("CoolSculpting takes the fat away, and PHYSIQ tones the muscle underneath so the area looks tight, not just smaller. The clients who add it love their results so much more. Want me to build a few sessions in?"));
c.push(moment("Everesse skin tightening, offered as the finish:"));
c.push(say("Once we reduce the fat here, a little skin tightening keeps everything smooth and firm. Should I show you how that fits into your plan?"));
c.push(moment("A second area, offered while she is set up:"));
c.push(say("We are already set up for today. If we treat the flanks at the same time as the abdomen, you get the whole waistline in one visit. Want me to add it?"));

c.push(group("During microneedling (SkinPen, RF, Gold Vampire)"));
c.push(moment("PRP upgrade, offered before you begin:"));
c.push(say("We can upgrade today with your own PRP, your body's growth factors, which speeds up healing and takes the results to another level. It is what we call the Vampire treatment. Want me to add it?"));
c.push(moment("LED to close, offered at the end:"));
c.push(say("Let's finish with LED to calm the skin and lock in the collagen boost. Want me to include it?"));

c.push(group("During laser hair removal"));
c.push(moment("A second small area, offered while she is set up:"));
c.push(say("You are already here and prepped. If you want, I can do your underarms too while we are at it, it only takes a few extra minutes. Want me to add that today?"));

c.push(group("During IV therapy, wellness, or a weight loss visit"));
c.push(moment("A vitamin or B-12 boost, offered as you start the drip:"));
c.push(say("Want me to add a B-12 or a vitamin boost to today's drip? It is a nice energy lift, and members get member pricing on it."));
c.push(moment("Peptides, offered when she mentions energy or recovery:"));
c.push(say("Based on what you are telling me about your energy and recovery, peptides might be a great next step. Want me to have the provider walk you through it?"));

// PART 2
c.push(h1("Part 2. Moving a Client Up a Tier"));
c.push(body("When a client's goals are bigger than her current tier, moving up is not a sale. It is handing her the plan that actually gets her there, usually for less than she is already spending. Use her consultation to find the trigger, then make the match."));

c.push(h2("Read the Trigger, Make the Match"));
c.push(triggerTable());
c.push(new Paragraph({ spacing: { after: 100 }, children: [new TextRun("")] }));

c.push(h2("The Words for Each Move"));
c.push(moment("Signature to Elite, $99 to $179:"));
c.push(say("You mentioned you want to tone up, and you are getting injectables here and there. Elite would actually save you money. You would get a body contouring session every month, a discount on your tox and filler, and a wellness boost included. For most clients in your shoes it pays for itself the first visit. Want me to switch you over so today counts?"));
c.push(moment("Elite to Prestige, $179 to $249:"));
c.push(say("Everything you told me about wanting firmer, younger-looking skin points to our Prestige level. You would get SkinPen, HydraFacial Platinum, or Everesse each month, fifteen percent off everything, and you can bank toward CoolSculpting if that is still a goal. It is seventy dollars more, but you are already spending more than that on add-ons. Want me to move you up?"));
c.push(moment("Prestige to VIP, $249 to $459:"));
c.push(say("You are in here often, and you love a full result. VIP gives you two signature treatments a month instead of one, twenty percent off everything, your hands done with CoolPeel, and a concierge line so you never wait for a spot. For how much you already do, VIP is our best value by far. Want me to set you up?"));

c.push(h2("Let the Math Close It"));
c.push(body("Add up what she came in for plus the add-ons she just said yes to. If that total is more than the next tier's monthly fee, the upgrade saves her money. Say the number out loud."));
c.push(say("You are doing a HydraFacial today, and you just added LED and a booster. That is already more than the Elite membership, and Elite gives you a facial every single month plus discounts. Want me to apply today's visit to a membership instead?"));

c.push(h2("Where to Start a Brand New Client"));
[["Comes in for facials and glow, watching her budget: ", "Amari Signature."],
 ["Wants body and skin, which is most people: ", "Amari Elite."],
 ["Focused on anti-aging or saving toward a device: ", "Amari Prestige."],
 ["Wants it all and will be in often: ", "Amari VIP."]].forEach(x => c.push(bulletBold(x[0], x[1])));

// PART 3
c.push(h1("Part 3. When She Hesitates"));
c.push(moment("\u201cLet me think about it.\u201d"));
c.push(say("Totally, no pressure. The one thing I will say is that today's visit can count toward your first month if you start now, so you are never paying twice. Want me to hold that for you?"));
c.push(moment("\u201cThat is a lot per month.\u201d"));
c.push(say("I hear you. The way to look at it is you are already planning to come in, and the membership makes each visit cheaper, not more. Most members spend less over the year, not more."));
c.push(moment("\u201cI am not sure I will use it every month.\u201d"));
c.push(say("That is the best part, nothing is ever lost. Whatever you do not use banks for twelve months, so it is always there waiting for you."));

// PART 4
c.push(h1("Part 4. The Checkout Close"));
c.push(body("Every checkout, do three things: tell her what she loved today, name the one next step, and offer the membership when the math favors it."));
c.push(say("You looked amazing walking out of here today. Same time next month? And if you want, I will set you up on the membership so today's treatment is already covered."));
c.push(rule());
c.push(body("Golden rule: never let a client pay full price for something a membership would have made cheaper without first showing her the membership. That single habit is what turns one visit into a year.", { bold: true, color: GREEN }));

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: CHAR } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: GREEN },
        paragraph: { spacing: { before: 280, after: 120 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 24, bold: true, font: "Arial", color: GOLD },
        paragraph: { spacing: { before: 180, after: 80 }, outlineLevel: 1 } },
    ],
  },
  numbering: { config: [
    { reference: "dot", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
      alignment: AlignmentType.LEFT,
      style: { run: { color: GOLD }, paragraph: { indent: { left: 460, hanging: 260 } } } }] },
  ] },
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 },
      margin: { top: 1296, right: 1440, bottom: 1296, left: 1440 } } },
    children: c,
  }],
});

Packer.toBuffer(doc).then(b => {
  fs.writeFileSync("/mnt/user-data/outputs/Amari_Vitality_In_Treatment_Upsell_Script.docx", b);
  console.log("done");
});

